foreach(['storage/secret.json'=>'private-data','includes/release_config.php'=>'private-config','.htaccess'=>'guard','pdf/sensitive.pdf'=>'pdf','svg/logo.svg'=>'logo','uploads/image.png'=>'image'] as $p=>$v) $assert(file_get_contents($app.'/'.$p)===$v,"Protected path remains unchanged: $p");
