$files['document-v1/index.php']='tampered'; $make($zipPath,$files);
$bad=portal_release_install_package($app,$zipPath,'','v1','v1',$plan2['manifest_sha256'],'github',$plan2['before']);
$assert(!($bad['ok'] ?? false) && file_get_contents($app.'/index.php')==='new-index','Changed archive after review is rejected');
