$files['other-v1/another.txt']='x'; $make($zipPath,$files); $assert(!(portal_github_release_compare($app,$zipPath,'v1')['ok'] ?? false),'Multiple roots rejected'); unset($files['other-v1/another.txt']);
$files['document-v1/assets/link.js']='target'; $make($zipPath,$files,'document-v1/assets/link.js'); $assert(!(portal_github_release_compare($app,$zipPath,'v1')['ok'] ?? false),'ZIP symlink rejected');
$temp=portal_release_create_temp_file((string)realpath($app));
$assert(is_string($temp) && !str_starts_with((string)realpath($temp),(string)realpath($app).DIRECTORY_SEPARATOR), 'Download temp file is outside application');
if (is_string($temp)) unlink($temp);
$files['document-v1/newroot.php']='ignored'; $files['document-v1/includes/newdir/new.php']='code'; $make($zipPath,$files);
$assert((portal_github_release_compare($app,$zipPath,'v1')['code'] ?? '')==='target_parent_missing','A missing destination directory blocks the plan');
